<?php
// bio.php - Bio link display page
require_once 'config.php';
require_once 'includes/db.php';
require_once 'includes/functions.php';

$db = new Database();
$username = $_GET['u'] ?? '';

if (empty($username)) {
    header('Location: index.php');
    exit;
}

$stmt = $db->prepare("SELECT b.*, u.username FROM bio_links b JOIN users u ON b.user_id = u.id WHERE b.username = ?");
$stmt->execute([$username]);
$bio = $stmt->fetch();

if (!$bio) {
    header('Location: index.php');
    exit;
}

// Update views
$db->prepare("UPDATE bio_links SET views = views + 1 WHERE id = ?")->execute([$bio['id']]);

$settings = getSettings($db);

// Get active advertisements
$stmt = $db->prepare("SELECT * FROM advertisements WHERE is_active = 1 ORDER BY position ASC LIMIT 1");
$stmt->execute();
$ad = $stmt->fetch();
?>
